107	    /** Fixed city-to-region table used to derive an owner's locality. */
108	    private static final Map<String, String> CITY_REGION = Map.of(
109	        "Sydney", "NSW",
110	        "Melbourne", "VIC",
111	        "Brisbane", "QLD");
