113	    /** Fixed region-to-postcode-range table (inclusive) used to validate a postcode. */
114	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
115	        "NSW", new int[] {2000, 2099},
116	        "VIC", new int[] {3000, 3099},
117	        "QLD", new int[] {4000, 4099});
