125	    /**
126	     * Return the owner's address. When a structured address is supplied (a non-blank
127	     * {@code addressLine1}) it takes precedence and the value is composed as the
128	     * normalized {@code addressLine1}, with a single space and the normalized
129	     * {@code addressLine2} appended when an {@code addressLine2} is present.
130	     * Otherwise the flat {@code address} is returned, preserving backward
131	     * compatibility for owners supplied in the flat form.
132	     */
133	    public String getAddress() {
134	        if (this.addressLine1 != null && !this.addressLine1.isBlank()) {
135	            if (this.addressLine2 != null && !this.addressLine2.isBlank()) {
136	                return this.addressLine1 + " " + this.addressLine2;
137	            }
138	            return this.addressLine1;
139	        }
140	        return this.address;
141	    }
