143	    /**
144	     * Set the owner's flat address, normalizing it to a canonical form so it is both
145	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
146	     * internal runs of whitespace are collapsed to a single space, the value is
147	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
148	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
149	     * left as-is.
150	     */
151	    public void setAddress(String address) {
152	        this.address = normalizeAddress(address);
153	    }
