159	    /**
160	     * Set the first line of the owner's structured address, normalized the same way
161	     * as the flat {@link #setAddress(String)} (trimmed, whitespace collapsed,
162	     * upper-cased, street-type abbreviations expanded). A {@code null} value is left
163	     * as-is.
164	     */
165	    public void setAddressLine1(String addressLine1) {
166	        this.addressLine1 = normalizeAddress(addressLine1);
167	    }
