173	    /**
174	     * Set the optional second line of the owner's structured address, normalized the
175	     * same way as {@link #setAddressLine1(String)}. A {@code null} value is left
176	     * as-is.
177	     */
178	    public void setAddressLine2(String addressLine2) {
179	        this.addressLine2 = normalizeAddress(addressLine2);
