182	    /**
183	     * Normalize an address string to its canonical form: trimmed, whitespace
184	     * collapsed, upper-cased, with common street-type abbreviations expanded.
185	     * Returns {@code null} for a {@code null} input; a value that is blank once
186	     * trimmed normalizes to the empty string.
187	     */
188	    public static String normalizeAddress(String address) {
189	        if (address == null) {
190	            return null;
191	        }
192	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
193	        if (collapsed.isEmpty()) {
194	            return "";
195	        }
196	        String[] tokens = collapsed.split(" ");
197	        StringBuilder sb = new StringBuilder();
198	        for (int i = 0; i < tokens.length; i++) {
199	            if (i > 0) {
200	                sb.append(' ');
201	            }
202	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
203	        }
204	        return sb.toString();
205	    }
