223	    /**
224	     * Return the stored E.164 telephone formatted for humans: a {@code '+'} and the
225	     * country code, a space, then the national digits grouped in threes and separated
226	     * by single spaces (for example {@code '+61412345678' -> '+61 412 345 678'}). The
227	     * North American country code ({@code '+1'}) is one digit; other country codes are
228	     * taken as two. Returns {@code null} when the telephone is not set, and returns the
229	     * raw value unchanged when it is not a well-formed E.164 number.
230	     */
231	    public String getTelephoneDisplay() {
232	        if (this.telephone == null || !this.telephone.matches("^\\+[0-9]+$")) {
233	            return this.telephone;
234	        }
235	        String digits = this.telephone.substring(1);
236	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
237	        if (digits.length() <= countryCodeLength) {
238	            return this.telephone;
239	        }
240	        String countryCode = digits.substring(0, countryCodeLength);
241	        String national = digits.substring(countryCodeLength);
242	        StringBuilder sb = new StringBuilder("+").append(countryCode);
243	        for (int i = 0; i < national.length(); i += 3) {
244	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
245	        }
246	        return sb.toString();
247	    }
