297	    /**
298	     * Return the owner's age band derived from the birth date, computed against the
299	     * registration date: {@code 'MINOR'} when under 18, {@code 'ADULT'} when 18 to
300	     * 64 inclusive, and {@code 'SENIOR'} when 65 or older. Returns {@code null} when
301	     * either the birth date or the registration date is not set.
302	     */
303	    public String getAgeBand() {
304	        if (this.birthDate == null || this.registrationDate == null) {
305	            return null;
306	        }
307	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
308	        if (age < 18) {
309	            return "MINOR";
310	        }
311	        if (age < 65) {
312	            return "ADULT";
313	        }
314	        return "SENIOR";
315	    }
