325	    /**
326	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
327	     * is always valid (postcode is optional). When present, a postcode is valid if
328	     * the city has no known region, or if it is four digits falling within the
329	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
330	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
331	     */
332	    public boolean isPostcodeValidForCity() {
333	        if (this.postcode == null) {
334	            return true;
335	        }
336	        String region = CITY_REGION.get(this.city);
337	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
338	        if (range == null) {
339	            return true;
340	        }
341	        if (!this.postcode.matches("^[0-9]{4}$")) {
342	            return false;
343	        }
344	        int value = Integer.parseInt(this.postcode);
345	        return value >= range[0] && value <= range[1];
346	    }
