356	    /**
357	     * Return a single Luhn check digit (0-9) computed over the digits contained in
358	     * the owner's customer code, or {@code null} when the customer code is not set.
359	     * Non-digit characters in the code are ignored; the rightmost digit is doubled
360	     * first, following the standard Luhn algorithm.
361	     */
362	    public Integer getCheckDigit() {
363	        if (this.customerCode == null) {
364	            return null;
365	        }
366	        int sum = 0;
367	        boolean doubleDigit = true;
368	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
369	            char c = this.customerCode.charAt(i);
370	            if (c < '0' || c > '9') {
371	                continue;
372	            }
373	            int digit = c - '0';
374	            if (doubleDigit) {
375	                digit *= 2;
376	                if (digit > 9) {
377	                    digit -= 9;
378	                }
379	            }
380	            sum += digit;
381	            doubleDigit = !doubleDigit;
382	        }
383	        return (10 - (sum % 10)) % 10;
384	    }
