386	    /**
387	     * Return the owner's membership number, formatted {@code '<customerCode>-M<YY>'}
388	     * where {@code YY} is the last two digits of the registration date's year (for
389	     * example {@code 'SMI-0007-M26'}). Returns {@code null} when either the customer
390	     * code or the registration date is not set.
391	     */
392	    public String getMembershipNumber() {
393	        if (this.customerCode == null || this.registrationDate == null) {
394	            return null;
395	        }
396	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
397	    }
