411	    /**
412	     * Return the owner's membership points, the raw score from which the
413	     * membership level is derived. Starting at {@code 0}, add {@code 2} when an
414	     * email address is present, {@code 1} when the owner has no namesakes
415	     * (namesake count is {@code 0}), {@code 2} for a household of {@code 3} or
416	     * more, and {@code 3} when the owner's tenure (days since the registration
417	     * date) exceeds {@code 365}.
418	     */
419	    public Integer getMembershipPoints() {
420	        int points = 0;
421	        boolean hasEmail = this.email != null && !this.email.isBlank();
422	        if (hasEmail) {
423	            points += 2;
424	        }
425	        if (this.namesakeCount != null && this.namesakeCount == 0) {
426	            points += 1;
427	        }
428	        if (this.householdSize != null && this.householdSize >= 3) {
429	            points += 2;
430	        }
431	        if (this.registrationDate != null
432	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
433	            points += 3;
434	        }
435	        return points;
436	    }
437	
438	    /**
439	     * Return the owner's membership level, a number from {@code 1} to {@code 4},
440	     * derived from {@link #getMembershipPoints()}: {@code 1} for {@code 0-1}
441	     * points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
442	     * {@code 4} for {@code 6} or more.
443	     */
444	    public Integer getMembershipLevel() {
445	        int points = getMembershipPoints();
446	        if (points >= 6) {
447	            return 4;
448	        }
449	        if (points >= 4) {
450	            return 3;
451	        }
452	        if (points >= 2) {
453	            return 2;
454	        }
455	        return 1;
456	    }
