508	    /**
509	     * Return the owner's locality (region), preferring the postcode: when the
510	     * postcode is present and falls within a known region's inclusive range
511	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
512	     * region is returned. Otherwise the value falls back to the fixed
513	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
514	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
515	     * table. This yields the same region for known cities but disambiguates
516	     * cities that share a name.
517	     */
518	    public String getLocality() {
519	        String regionFromPostcode = regionForPostcode();
520	        if (regionFromPostcode != null) {
521	            return regionFromPostcode;
522	        }
523	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
524	    }
525	
526	    /**
527	     * Return the owner's IANA timezone, derived from the locality/region via the
528	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
529	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or
530	     * {@code null} when the region is not in the table.
531	     */
532	    public String getTimezone() {
533	        return REGION_TIMEZONE.get(getLocality());
534	    }
535	
536	    /**
537	     * Look up the region whose inclusive postcode range contains this owner's
538	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
539	     * known range.
540	     */
541	    private String regionForPostcode() {
542	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
543	            return null;
544	        }
545	        int value = Integer.parseInt(this.postcode);
546	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
547	            int[] range = entry.getValue();
548	            if (value >= range[0] && value <= range[1]) {
549	                return entry.getKey();
550	            }
551	        }
552	        return null;
553	    }
