555	    /**
556	     * Return the owner's preferred contact channel, derived from the stored
557	     * contact details: {@code 'EMAIL'} when an email address is present,
558	     * otherwise {@code 'PHONE'}.
559	     */
560	    public String getContactPreference() {
561	        boolean hasEmail = this.email != null && !this.email.isBlank();
562	        return hasEmail ? "EMAIL" : "PHONE";
563	    }
