565	    /**
566	     * Return the owner's derived identity key, which consolidates all duplicate
567	     * detection into a single value formed as
568	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}.
569	     * The telephone and email are already stored in their normalized (E.164 /
570	     * lower-cased) forms; a missing email or household id contributes an empty
571	     * segment. A create is rejected only when a new owner's whole identity key
572	     * equals an existing owner's.
573	     */
574	    public String getIdentityKey() {
575	        String telephonePart = this.telephone == null ? "" : this.telephone;
576	        String emailPart = (this.email == null) ? "" : this.email;
577	        String householdPart = (this.householdId == null) ? "" : this.householdId;
578	        return telephonePart + "|" + emailPart + "|" + householdPart;
579	    }
