105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
119	        if (normalizedTelephone == null) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        if (isDisposableEmailDomain(ownerFieldsDto.getEmail())) {
123	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	        }
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        // The owner must supply an address in EITHER form: a non-blank structured
127	        // 'addressLine1' or the flat 'address'. getAddress() prefers the structured
128	        // fields (composing line 1 with an optional line 2) and falls back to the flat
129	        // value; a blank result means neither form was provided. The composed value is
130	        // written back so the persisted flat 'address' stays consistent with it.
131	        String composedAddress = owner.getAddress();
132	        if (composedAddress == null || composedAddress.isBlank()) {
133	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
134	        }
135	        owner.setAddress(composedAddress);
136	        owner.setTelephone(normalizedTelephone);
137	        if (!owner.isPostcodeValidForCity()) {
138	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
139	        }
140	        // The household id is deterministic: it is derived purely from the owner's
141	        // (last name, postcode), so every owner at the same last name and postcode resolves
142	        // to the same value. It is assigned up front, before any duplicate detection, so the
143	        // identity key and the household check below both key off it.
144	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
145	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
146	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
147	        // identityKey (telephone|email|householdId) equals an existing owner's. With the
148	        // household id now computed up front, two members of one household still differ here
149	        // whenever their telephone or email differs, and so are both allowed.
150	        String identityKey = owner.getIdentityKey();
151	        if (this.clinicService.findAllOwners().stream()
152	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
153	            return new ResponseEntity<>(HttpStatus.CONFLICT);
154	        }
155	        // Household duplicate: because the household is keyed on (last name, postcode), any
156	        // existing owner sharing this computed household id is the same household. A second
157	        // such owner is rejected as a household duplicate (409) unless it explicitly declares
158	        // 'sharesHousehold', which now only bypasses this block (the link is no longer created
159	        // here — the id is computed).
160	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
161	        if (!householdMembers.isEmpty() && !sharesHousehold) {
162	            return new ResponseEntity<>(HttpStatus.CONFLICT);
163	        }
164	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
165	            return new ResponseEntity<>(HttpStatus.CONFLICT);
166	        }
167	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
168	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
169	        }
170	        LocalDate effectiveDate =
171	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
172	        LocalDate registrationDate = toBusinessDay(effectiveDate);
173	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
174	        if (ownersRegisteredToday >= 100) {
175	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
176	        }
177	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
178	        HttpHeaders headers = new HttpHeaders();
179	        owner.setRegistrationDate(registrationDate);
180	        owner.setCustomerCode(customerCode(owner));
181	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
182	        owner.setBulkSignupWarning(bulkSignupWarning);
183	        // The household size (an input to the membership computation) keys off the computed
184	        // household id: this owner plus everyone already sharing it.
185	        owner.setHouseholdSize(householdMembers.size() + 1);
186	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
187	        // duplicate, so only a non-declared create is scored. In practice a non-declared owner
188	        // sharing an existing owner's last name and postcode is already rejected above as a
189	        // household duplicate, so this now only ever confirms the owner is not a duplicate.
190	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
191	        owner.setPossibleDuplicate(possibleDuplicate != null);
192	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
193	        this.clinicService.saveOwner(owner);
194	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
195	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
196	            owner.getMembershipNumber());
197	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
211	        if (normalizedTelephone == null) {
212	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
213	        }
214	        currentOwner.setAddress(ownerFieldsDto.getAddress());
215	        currentOwner.setCity(ownerFieldsDto.getCity());
216	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
217	        currentOwner.setLastName(ownerFieldsDto.getLastName());
218	        currentOwner.setTelephone(normalizedTelephone);
219	        currentOwner.setEmail(ownerFieldsDto.getEmail());
220	        this.clinicService.saveOwner(currentOwner);
221	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
222	    }
